const commits = $('Get Commits (Last 7 Days)').all();
const issues = $('Get Closed Issues (Last 7 Days)').all();
const prs = $('Get Merged PRs (Last 7 Days)').all();

const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

const commitSummaries = commits
  .filter(c => c.json.commit)
  .slice(0, 20)
  .map(c => `- ${c.json.commit.message.split('\n')[0]} (by ${c.json.commit.author.name})`);

const issueSummaries = issues
  .filter(i => !i.json.pull_request && new Date(i.json.closed_at) > weekAgo)
  .slice(0, 15)
  .map(i => `- #${i.json.number}: ${i.json.title}`);

const prSummaries = prs
  .filter(p => p.json.merged_at && new Date(p.json.merged_at) > weekAgo)
  .slice(0, 15)
  .map(p => `- #${p.json.number}: ${p.json.title} (by ${p.json.user?.login})`);

const repo = $vars.GITHUB_REPO || 'unknown/repo';
const language = $vars.SUMMARY_LANGUAGE || 'EN';

const langInstruction = language === 'FR'
  ? 'Write the summary in French.'
  : 'Write the summary in English.';

const prompt = `You are a senior engineering lead writing a weekly digest for your team.

${langInstruction}

Here is the activity from repository "${repo}" over the past 7 days:

## Commits (${commitSummaries.length})
${commitSummaries.length > 0 ? commitSummaries.join('\n') : 'No commits this week.'}

## Closed Issues (${issueSummaries.length})
${issueSummaries.length > 0 ? issueSummaries.join('\n') : 'No issues closed this week.'}

## Merged Pull Requests (${prSummaries.length})
${prSummaries.length > 0 ? prSummaries.join('\n') : 'No PRs merged this week.'}

Write a clear, narrative weekly summary (3–5 paragraphs) that:
1. Opens with a high-level overview of the week
2. Highlights the most important work shipped
3. Notes any patterns or recurring themes
4. Ends with a forward-looking sentence about momentum

Tone: professional but human. No bullet points — flowing prose only.`;

return [{ json: { prompt, repo, language, commitCount: commitSummaries.length, issueCount: issueSummaries.length, prCount: prSummaries.length } }];

const claudeResponse = $input.first().json;
const prevData = $('Build Claude Prompt').first().json;

const summaryText = claudeResponse.content?.[0]?.text || 'Error: no content returned from Claude.';

const subject = `Weekly Dev Summary — ${prevData.repo} — ${new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}`;

const htmlBody = `
<html>
<body style="font-family: Georgia, serif; max-width: 700px; margin: 0 auto; padding: 20px; color: #222;">
  <h2 style="color: #1a1a2e; border-bottom: 2px solid #4a90d9; padding-bottom: 8px;">Weekly Dev Summary</h2>
  <p style="color: #666; font-size: 14px;">Repository: <strong>${prevData.repo}</strong> &nbsp;|&nbsp; Week ending: ${new Date().toLocaleDateString()}</p>
  <hr style="border: none; border-top: 1px solid #eee;" />
  <div style="line-height: 1.8; font-size: 16px;">
    ${summaryText.split('\n\n').map(p => `<p>${p}</p>`).join('')}
  </div>
  <hr style="border: none; border-top: 1px solid #eee;" />
  <p style="color: #999; font-size: 12px;">Stats: ${prevData.commitCount} commits, ${prevData.issueCount} issues closed, ${prevData.prCount} PRs merged &nbsp;|&nbsp; Generated by Claude ${prevData.language === 'FR' ? '(FR)' : '(EN)'}</p>
</body>
</html>`;

return [{ json: { subject, htmlBody, summaryText, repo: prevData.repo } }];

